export default function SecurityPageGolden() {
  return (
    <>
<div><a className="skip" href="#main">Skip to content</a><header className="nav"><div className="wrap navin"><a className="brand" href="/" aria-label="TheDiligence, home"><span className="mark" aria-hidden="true"><i style={{height:"12px",background:"var(--blue)"}}></i><i style={{height:"22px",background:"var(--orange)"}}></i><i style={{height:"16px",background:"var(--green)"}}></i></span>TheDiligence</a><nav className="links" aria-label="Main"><a href="/products">Products</a><a href="/solutions">Solutions</a><a href="/method">Method</a><a href="/security" aria-current="page">Security</a><a href="/about">About</a></nav><div className="navr"><a className="btn btn-s btn-sm" href="/book">Book time</a><a className="btn btn-p btn-sm" href="/platform#start">Start free</a><details className="menu"><summary aria-label="Open menu"><span className="burger" aria-hidden="true"></span></summary><div className="menu-p"><a href="/products">Products</a><a href="/solutions">Solutions</a><a href="/method">Method</a><a href="/security" aria-current="page">Security</a><a href="/about">About</a><a href="/platform">Platform</a><a href="/insights">Insights</a><a href="/book">Book time</a></div></details></div></div></header><main id="main"><section className="page-hero" aria-label="Security and compliance"><div className="wrap"><div className="stack-m" style={{maxWidth:"1000px"}}><p className="eyebrow">Security and compliance</p><h1 className="h1">Built for data <em>that cannot leave the building.</em></h1><p className="lead">Agents work inside sandboxes that hold no keys, reach only the hosts you expect, and cannot send anything anywhere. This page says how, what is built and what is not, so your review starts from facts.</p><div className="row"><span className="tag"><i className="dot" style={{color:"var(--green)"}}></i>No key in a sandbox</span><span className="tag"><i className="dot" style={{color:"var(--blue)"}}></i>Three data classes</span><span className="tag"><i className="dot" style={{color:"var(--orange)"}}></i>Status shown on every control</span></div><div className="row"><a className="btn btn-p" href="/book">Request a security review<svg className="ic ic-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><path d="M5 12h14M13 6l6 6-6 6" /></svg></a><a className="btn btn-s" href="#compliance">Compliance status</a></div></div><nav className="subnav" aria-label="On this page"><a href="#architecture">Keys</a><a href="#data">Data classes</a><a href="#controls">Controls</a><a href="#agents">What agents cannot do</a><a href="#compliance">Compliance</a></nav></div></section><section className="band night sec" id="architecture" aria-label="How keys are protected"><div className="wrap"><div className="head"><p className="eyebrow">Keys and models</p><h2 className="h2">A pasted key is the last resort. <em>No key near an agent.</em></h2><p className="lead">Model-written code is the riskiest thing in the system, so it is the one place that never holds a secret. You connect your provider through a third party, a run gets a token that is worth nothing outside this run, and a broker does the rest.</p></div><ol className="bk" aria-label="How a model call travels from a run to your provider"><li className="bk-n"><span className="bk-k mono">1 · You</span><b>Your provider account</b><p>You approve access on your provider's own screen where the provider allows it. Where it does not, you can paste a key as a last resort: it is encrypted, never visible to agents, and you can delete it in one click.</p><span className="bk-h"><svg className="ic ic-key" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><circle cx="8" cy="15" r="3.5" /><path d="M10.5 12.5L19 4M16 7l3 3M14 9l2 2" /></svg>Your key, when you must paste one, is encrypted</span></li><li className="bk-n"><span className="bk-k mono">2 · Run</span><b>Workflow</b><p>Starts the run and mints a short-lived token, valid for this workspace, this target, this budget and these models.</p><span className="bk-h"><svg className="ic ic-clock" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="9" /><path d="M12 7v5l3 2" /></svg>Holds a token that expires with the run</span></li><li className="bk-n bk-no"><span className="bk-k mono">3 · Work</span><b>Sandbox</b><p>Where the agents read and write. Documents are mounted read-only. Only a short list of hosts can be reached.</p><span className="bk-h"><svg className="ic ic-lock" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><rect x="5" y="11" width="14" height="9" rx="2" /><path d="M8 11V8a4 4 0 0 1 8 0v3" /></svg>Holds the token. No credential, ever</span></li><li className="bk-n"><span className="bk-k mono">4 · Swap</span><b>Connection broker</b><p>Turns the token into one call to your provider through your connection, checks the budget, and records the cost.</p><span className="bk-h"><svg className="ic ic-shield" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><path d="M12 3l7 3v5c0 4.5-3 8.2-7 10-4-1.8-7-5.5-7-10V6z" /><path d="M9 12l2.2 2.2L15 10.5" /></svg>Reaches your provider one call at a time</span></li><li className="bk-n"><span className="bk-k mono">5 · Model</span><b>Your provider</b><p>Sees an ordinary call from your account. The bill lands with you, not with us.</p><span className="bk-h"><svg className="ic ic-file" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><path d="M7 3h7l5 5v13H7z" /><path d="M14 3v5h5M10 13h6M10 17h6" /></svg>Your account, your terms</span></li></ol><div className="bk3"><div><b>The token dies with the run</b><span className="body">It is scoped to one workspace, one target, a budget and a list of models. After the run, it opens nothing.</span></div><div><b>The budget is enforced outside the sandbox</b><span className="body">The broker counts every call. When the cap is reached the run stops, whatever the agent wants.</span></div><div><b>A build fails if a credential leaks</b><span className="body">A test searches the sandbox environment and its logs for credential patterns on every build.</span></div></div><div className="row" style={{marginTop:"40px",alignItems:"center"}}><span className="status st-live">At launch</span><span className="small" style={{color:"rgb(196, 200, 206)"}}>Provider connections for Claude, OpenAI, Mistral and Gemini, run tokens, the broker and the egress allowlist ship with the first release.</span></div></div></section><section className="sec" id="data" aria-label="Data classes"><div className="wrap"><div className="head"><p className="eyebrow">Data classes</p><h2 className="h2">Every document has a class. <em>The class decides who may read it.</em></h2><p className="lead">A class is set when a document comes in and shown on every row of the ledger. Before you launch, the plan tells you which provider will read which class.</p></div><div className="tbl-wrap"><table className="tbl"><thead><tr><th scope="col">Class</th><th scope="col">What it is</th><th scope="col">Which models may read it</th><th scope="col">Where it goes</th></tr></thead><tbody><tr><td>Public</td><td>Websites, filings, press, anything anyone can open.</td><td>Any model you connect.</td><td>Your ledger, with the source id and the date retrieved.</td></tr><tr><td>Target-confidential</td><td>What the target shared with you: decks, data-room exports, financials, call notes.</td><td>Only providers that do not retain or train on your traffic, under a data processing agreement.</td><td>Your workspace only. Deleted with the target. Exports are watermarked.</td></tr><tr><td>Fund-internal</td><td>Your thesis, partner notes, term sheets, references.</td><td>Same as above, and only for the targets and runs you allow.</td><td>Your vault, hosted by us and encrypted in your browser, or kept in Obsidian from Pro. A note reaches a run only when you share it.</td></tr></tbody></table></div><p className="small" style={{marginTop:"24px",maxWidth:"70ch"}}>Logs, traces and analytics carry ids and costs. They never carry evidence, prompts or keys.</p></div></section><section className="sec alt" id="controls" aria-label="Controls"><div className="wrap"><div className="head"><p className="eyebrow">Controls</p><h2 className="h2">What we have built, <em>what is on its way.</em></h2><p className="lead">Each control carries a status. At launch means it ships with the first release. Next and Later are on our roadmap, and we do not describe them as done.</p></div><div className="g3" style={{rowGap:"40px"}}><div className="ctl"><div className="row"><span className="ic-b"><svg className="ic ic-users ic-l" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><circle cx="9" cy="8" r="3.2" /><path d="M3 20c0-3.3 2.7-6 6-6s6 2.7 6 6" /><circle cx="17" cy="9" r="2.4" /><path d="M17 14c2.5 0 4.2 2 4.2 5" /></svg></span><span className="status st-live">At launch</span></div><h3 className="h4">Access</h3><p className="body">Sign-in by one-time email code, rate-limited and usable once. Roles per workspace. The database itself refuses to show one workspace the rows of another.</p></div><div className="ctl"><div className="row"><span className="ic-b"><svg className="ic ic-key ic-l" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><circle cx="8" cy="15" r="3.5" /><path d="M10.5 12.5L19 4M16 7l3 3M14 9l2 2" /></svg></span><span className="status st-live">At launch</span></div><h3 className="h4">Provider connections</h3><p className="body">You approve access on your provider's own screen where the provider allows it, and you can revoke it at any time. Where it does not, a pasted key is the last resort: encrypted, never visible to agents, deleted in one click.</p></div><div className="ctl"><div className="row"><span className="ic-b"><svg className="ic ic-layers ic-l" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><path d="M12 4l9 5-9 5-9-5z" /><path d="M3 14l9 5 9-5" /></svg></span><span className="status st-live">At launch</span></div><h3 className="h4">Sandboxes</h3><p className="body">One isolated sandbox per branch of a run. Evidence is mounted read-only. Each step reaches only the hosts it needs: search, the target's own domains, package registries.</p></div><div className="ctl"><div className="row"><span className="ic-b"><svg className="ic ic-eye ic-l" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><path d="M2 12s3.6-6.5 10-6.5S22 12 22 12s-3.6 6.5-10 6.5S2 12 2 12z" /><circle cx="12" cy="12" r="2.8" /></svg></span><span className="status st-live">At launch</span></div><h3 className="h4">Untrusted documents</h3><p className="body">A founder deck can contain instructions. We treat every document as data, never as a command, and agents have no tool that could act on one.</p></div><div className="ctl"><div className="row"><span className="ic-b"><svg className="ic ic-clock ic-l" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="9" /><path d="M12 7v5l3 2" /></svg></span><span className="status st-live">At launch</span></div><h3 className="h4">Run log and retention</h3><p className="body">Every tool call, decision and cost goes to an append-only log you can replay. Evidence goes when the target does, and a retention policy can be set per workspace.</p></div><div className="ctl"><div className="row"><span className="ic-b"><svg className="ic ic-download ic-l" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><path d="M12 4v11M7 11l5 5 5-5M5 20h14" /></svg></span><span className="status st-live">At launch</span></div><h3 className="h4">Sharing and export</h3><p className="body">Links are scoped to the workspace and expire. File links are signed and short-lived. Exports carry the workspace and the date. Everything can be exported.</p></div><div className="ctl"><div className="row"><span className="ic-b"><svg className="ic ic-globe ic-l" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="9" /><path d="M3 12h18M12 3c2.5 2.6 3.8 5.6 3.8 9s-1.3 6.4-3.8 9c-2.5-2.6-3.8-5.6-3.8-9S9.5 5.6 12 3z" /></svg></span><span className="status st-build">Next</span></div><h3 className="h4">Europe mode</h3><p className="body">Sandboxes hosted in the EU first. A Europe-only mode follows, where models are restricted to European regions or to a European provider.</p></div><div className="ctl"><div className="row"><span className="ic-b"><svg className="ic ic-lock ic-l" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><rect x="5" y="11" width="14" height="9" rx="2" /><path d="M8 11V8a4 4 0 0 1 8 0v3" /></svg></span><span className="status st-live">At launch</span></div><h3 className="h4">Vault</h3><p className="body">Hosted by us and encrypted in your browser: we store ciphertext and cannot read it. From Pro, an Obsidian plugin keeps notes in your own vault instead, and we hold no key to them. Agents cannot read either, unless a member shares a note for one target, and the share is logged.</p></div><div className="ctl"><div className="row"><span className="ic-b"><svg className="ic ic-shield ic-l" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><path d="M12 3l7 3v5c0 4.5-3 8.2-7 10-4-1.8-7-5.5-7-10V6z" /><path d="M9 12l2.2 2.2L15 10.5" /></svg></span><span className="status st-plan">Later</span></div><h3 className="h4">Single sign-on and audit log</h3><p className="body">SAML sign-on for the whole team, and an audit log of who opened what, for the Fund plan.</p></div></div></div></section><section className="band night sec" id="agents" aria-label="What agents cannot do"><div className="wrap"><div className="head"><p className="eyebrow">Limits on the agents</p><h2 className="h2">What an agent <em>can never do.</em></h2><p className="lead">These are rules built into the product, not promises in a policy.</p></div><ul className="never"><li><span className="x"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6L6 18" /></svg></span><span>Hold or read your provider credentials.</span></li><li><span className="x"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6L6 18" /></svg></span><span>Send, post or email anything. Agents draft, people send.</span></li><li><span className="x"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6L6 18" /></svg></span><span>Reach a host that is not on the list for that step.</span></li><li><span className="x"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6L6 18" /></svg></span><span>Write a claim without a source, unless it is graded C and says so.</span></li><li><span className="x"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6L6 18" /></svg></span><span>Spend past the budget you set.</span></li><li><span className="x"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6L6 18" /></svg></span><span>Give a verdict without a person approving it at the gate.</span></li></ul></div></section><section className="sec" id="compliance" aria-label="Compliance status"><div className="wrap"><div className="head"><p className="eyebrow">Compliance</p><h2 className="h2">Compliance, <em>stated plainly.</em></h2></div><div className="honest" style={{marginBottom:"48px"}}><svg className="ic ic-shield ic-l" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false" style={{color:"var(--orange-t)"}}><path d="M12 3l7 3v5c0 4.5-3 8.2-7 10-4-1.8-7-5.5-7-10V6z" /><path d="M9 12l2.2 2.2L15 10.5" /></svg><div><b>We hold no certification today.</b><span className="body">We would rather say so than imply otherwise. Below is what is in place and what we are working toward, so you can judge whether it is enough for your deal.</span></div></div><div className="tbl-wrap"><table className="tbl"><thead><tr><th scope="col">Item</th><th scope="col">Status</th><th scope="col">What it means</th></tr></thead><tbody><tr><td>Data processing agreement</td><td><span className="status st-live">At launch</span></td><td>We sign one with you on request, and hold one with each subprocessor listed below.</td></tr><tr><td>Security pass before launch</td><td><span className="status st-live">At launch</span></td><td>Content security policy, rate limits, token and egress tests, a test deck that carries hostile instructions, dependency scanning, and key rotation, all checked before release.</td></tr><tr><td>Incident process and status page</td><td><span className="status st-live">At launch</span></td><td>A written process, and a public page showing the health of the service.</td></tr><tr><td>Hosting region</td><td><span className="status st-live">At launch</span></td><td>United States. Europe sandboxes follow, then a Europe-only mode.</td></tr><tr><td>Independent penetration test</td><td><span className="status st-plan">Later</span></td><td>Planned after the first release.</td></tr><tr><td>SOC 2 Type I (Later)</td><td><span className="status st-plan">Later</span></td><td>Budgeted for the second year. It is a prerequisite for the Fund plan.</td></tr></tbody></table></div><div className="head" style={{marginTop:"96px"}}><p className="eyebrow">Subprocessors</p><h3 className="h3">Who touches your data, <em>and why.</em></h3><p className="body" style={{maxWidth:"70ch"}}>The model providers you connect are not our subprocessors. They run on your own accounts, under your terms.</p></div><div className="subp"><div><b>Vercel</b><span>Hosting, sandboxes, file storage</span></div><div><b>Neon</b><span>Database</span></div><div><b>Resend</b><span>Sign-in codes, invites, notifications</span></div><div><b>Stripe</b><span>Billing, when enabled</span></div><div><b>Sentry</b><span>Errors, with no document content</span></div><div><b>Axiom</b><span>Traces and logs, with no document content</span></div><div><b>PostHog, EU</b><span>Product analytics, on public and onboarding pages</span></div><div><b>Connection service</b><span>Provider authorisation, so we never hold your keys</span></div><div><b>Your providers</b><span>Claude, OpenAI, Mistral and Gemini, on your own accounts</span></div></div></div></section><section className="band night cta-band" aria-label="Request a security review"><svg className="routes-low" viewBox="0 0 1800 200" width="1800" height="200" aria-hidden="true" focusable="false" preserveAspectRatio="xMidYMax slice"><g fill="none" strokeWidth="8" strokeLinecap="round" strokeLinejoin="round"><path d="M0 70 H260 L320 130 H560 L620 70 H900" stroke="#2356C4" /><path d="M1800 60 H1560 L1500 120 H1240 L1180 60 H900" stroke="#D9640F" /><path d="M0 150 H420 L480 190 H760" stroke="#12855A" /><path d="M1800 160 H1380 L1320 190 H1040" stroke="currentColor" style={{color:"var(--fg)"}} /></g><g strokeWidth="5" style={{fill:"var(--bg)"}}><circle cx="320" cy="130" r="10" stroke="#2356C4" /><circle cx="560" cy="130" r="10" stroke="#2356C4" /><circle cx="1500" cy="120" r="10" stroke="#D9640F" /><circle cx="1240" cy="120" r="10" stroke="#D9640F" /><circle cx="480" cy="190" r="10" stroke="#12855A" /><circle cx="1320" cy="190" r="10" stroke="currentColor" style={{color:"var(--fg)"}} /></g></svg><div className="wrap"><div className="stack-m" style={{alignItems:"center"}}><h2 className="h2" style={{maxWidth:"18ch"}}>Bring your questionnaire. <em>We answer in writing.</em></h2><p className="lead" style={{maxWidth:"56ch",textAlign:"center",color:"rgb(196, 200, 206)"}}>Send your security review with the deal. We reply with the architecture, the data flow and the status of every control, before the first call.</p><div className="row" style={{justifyContent:"center"}}><a className="btn btn-p" href="/book">Request a security review<svg className="ic ic-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><path d="M5 12h14M13 6l6 6-6 6" /></svg></a><a className="btn btn-s" href="/platform#roadmap">See the roadmap</a></div></div></div></section></main><footer className="foot"><div className="wrap"><div className="footg"><div className="stack-m"><a className="brand" href="/" aria-label="TheDiligence, home"><span className="mark" aria-hidden="true"><i style={{height:"12px",background:"var(--blue)"}}></i><i style={{height:"22px",background:"var(--orange)"}}></i><i style={{height:"16px",background:"var(--green)"}}></i></span>TheDiligence</a><p className="body" style={{maxWidth:"34ch"}}>Skilled agents, orchestrated for evidence. Built by operator-investors, for operator-investors.</p><p className="small">Paris and London</p></div><div><h4>Product</h4><ul><li><a href="/products">Products</a></li><li><a href="/platform">Platform and plans</a></li><li><a href="/method">The method</a></li><li><a href="/security">Security and compliance</a></li></ul></div><div><h4>Work with us</h4><ul><li><a href="/solutions">Solutions</a></li><li><a href="/solutions#hire">Hire us</a></li><li><a href="/book">Book time</a></li><li><a href="/platform#start">Start free</a></li></ul></div><div><h4>Company</h4><ul><li><a href="/about">About us</a></li><li><a href="/insights">Insights</a></li><li><a href="https://www.linkedin.com/in/ismaelghozael/" target="_blank" rel="noopener">Ismael Ghozael</a></li><li><a href="https://www.linkedin.com/in/mazenwazni/" target="_blank" rel="noopener">Mazen Wazni</a></li></ul></div></div><div className="footb"><span>TheDiligence is a working name.</span><span>Evidence-graded analysis, not investment advice.</span></div></div></footer></div>
    </>
  );
}
